export function getExpansionNiche(idOrName: number | string): ExpandedNiche | undefined {
  if (typeof idOrName === 'number') {
    return EXPANSION_NICHES.find(n => n.id === idOrName);
  }
  const q = idOrName.toLowerCase();
  return EXPANSION_NICHES.find(n =>
    n.nicheTag.toLowerCase().includes(q) ||
    n.category.toLowerCase().includes(q)
  );
}

export function getExpansionCard(cardId: string): ExpandedRolePromptCard | undefined {
  return ALL_EXPANSION_CARDS.find(c => c.cardId.toLowerCase() === cardId.toLowerCase());
}

export function isExpansionNiche(nicheName: string): boolean {
  const q = nicheName.toLowerCase();
  return EXPANSION_NICHES.some(n =>
    n.nicheTag.toLowerCase().includes(q) ||
    q.includes(n.nicheTag.toLowerCase())
  );
}
